    for pp in permutations(range(n)):
        sign=(-1)**sum(pp[i]>pp[j] for i in range(n) for j in range(i+1,n));term=constant(sign)
        for i,j in enumerate(pp):term=mul(term,M[i][j])
        out=add(out,term)
    return out
